Lemma onreq_spec : onreq_stmt H.
Proof.
  intros until errv. intros.
  eapply (ah_mono H HH); [eapply onreq_spec2; eassumption|].
  intros c' PO. unfold onreq_post2 in PO. unfold onreq_post.
  destruct PO as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m' & errv' & s' & LB' & h' & XS & PO).
  exists t0', t1', t2', a0', a1', a2', a3', a4', a5', a6', a7', t3', t4', t5', t6', m', errv', s', LB', h', XS.
  repeat (lazymatch goal with |- _ /\ _ => split; [apply (proj1 PO)| apply proj2 in PO] | _ => apply (proj1 PO) end).
Qed.

End HCW.
